-- BadbUI - Italian overrides. Italian source phrases fall back to themselves.
local _, ns = ...
ns.Badb.Localization:RegisterLocale("itIT", {
    ["Profiles"] = "Profili",
    ["Modules"] = "Moduli",
    ["Frames"] = "Frame",
    ["Unlock"] = "Sblocca frame",
    ["Language"] = "Lingua",
    ["Automatic (client language)"] = "Automatica (lingua del client)",
    ["Language changes take effect after /reload. Macro spell names stay in English."] = "Il cambio lingua si applica dopo /reload. I nomi delle abilita' nelle macro restano in inglese.",
    ["Language preference: %s. Active language: %s."] = "Lingua scelta: %s. Lingua attiva: %s.",
    ["Language saved. Use /reload to apply it."] = "Lingua salvata. Usa /reload per applicarla.",
    ["Language saved."] = "Lingua salvata.",
    ["Language must be auto, enUS or itIT."] = "La lingua deve essere auto, enUS o itIT.",
    ["language [auto|enUS|itIT] - choose the addon language (requires /reload)"] = "language [auto|enUS|itIT] - scegli la lingua dell'addon (richiede /reload)",
})

-- Built-in manual.
ns.Badb.Localization:RegisterLocale("itIT", {
    ["Start here"] = "Inizia da qui",
    ["Welcome to BadbUI, a modular interface for WoW: Forever. This manual is available inside the addon without a website or internet connection. Guild synchronization needs the companion and its server.\n1. Type /badb (or /bui) to open settings. Use the sidebar or the search field to find a page or option.\n2. Run /badb setup for guided setup. Choose your content and role, review the changes, then apply. Confirm the role yourself if detection is uncertain.\n3. Open Home to turn individual modules on or off. Open a module's options to customize it.\n4. Create a backup before making large changes. Use the Help topics below whenever you need a reference.\nUse the Topic menu to read one subject, choose All topics for the complete manual, or search to find text across every topic."] = "Benvenuto in BadbUI, un'interfaccia modulare per WoW: Forever. Questo manuale si consulta nell'addon anche senza sito o connessione internet. La sincronizzazione di gilda richiede il companion e il suo server.\n1. Scrivi /badb (oppure /bui) per aprire le impostazioni. Usa la sidebar o il campo di ricerca per trovare pagine e opzioni.\n2. Avvia /badb setup per la configurazione guidata. Scegli contenuto e ruolo, controlla le modifiche e applicale. Conferma tu il ruolo se il rilevamento e' incerto.\n3. Apri Principale per accendere o spegnere i singoli moduli. Apri le opzioni del modulo per personalizzarlo.\n4. Crea un backup prima di modifiche importanti. Consulta gli argomenti Help quando ti serve un riferimento.\nUsa il menu Argomento per leggere una sezione, scegli Tutti gli argomenti per il manuale completo oppure cerca nel testo di tutte le sezioni.",
    ["Language and worldwide use"] = "Lingua e uso nel mondo",
    ["Open Appearance > Language, or type /badb language enUS for English, /badb language itIT for Italian, or /badb language auto to follow the client. Apply a change with /reload. The preference applies to the whole addon, across profiles.\nAutomatic mode uses Italian on an Italian client and English on all other clients, including enGB. English and Italian are the supported interface languages; other client languages currently use English.\nSlash commands, module IDs and saved profile data stay the same in both languages. Your own profile names, scripts, guild posts and server content are shown as written by their authors.\nThe built-in macro catalog and spell names remain in English. On a non-English game client, check the localized spell names before using a macro; changing the interface language does not translate the game or its spells. The macro command help documents individual spell-name overrides."] = "Apri Aspetto > Lingua, oppure scrivi /badb language enUS per l'inglese, /badb language itIT per l'italiano o /badb language auto per seguire il client. Applica il cambio con /reload. La scelta vale per tutto l'addon e per tutti i profili.\nLa modalita' automatica usa l'italiano sul client italiano e l'inglese sugli altri client, incluso enGB. Le lingue dell'interfaccia supportate sono inglese e italiano; le altre lingue del client usano per ora l'inglese.\nComandi, ID dei moduli e dati salvati dei profili restano uguali nelle due lingue. I tuoi nomi di profilo, script, messaggi di gilda e contenuti del server sono mostrati come li hanno scritti gli autori.\nIl catalogo macro e i nomi delle abilita' restano in inglese. Su un client di gioco non inglese, controlla i nomi localizzati prima di usare una macro: cambiare lingua all'addon non traduce il gioco o le abilita'. L'aiuto del comando macro descrive le sostituzioni dei singoli nomi.",
    ["Profiles, presets and backups"] = "Profili, preset e backup",
    ["Profiles keep separate module settings and frame layouts. In Profiles you can create, copy, rename, switch, import, export or delete a profile. You can also assign profiles to talent groups where the client supports them. /badb profile lists profiles; /badb profile <name> selects one.\nPresets provide starting layouts for class, role, PvE and PvP. Read the preview before applying. The preset workflow creates a backup and normally a new profile. /badb undo reverts the last preset operation when its previous profile still exists.\nBackups are saved snapshots for recovery. Create one before experimenting, then restore or export it from Backups. Profile export and backup export have different scopes: read the import preview before applying either one.\nImport / Export lets you copy a full profile or one module's options. Copy the complete generated string. Importing settings does not install other addons or create profiles inside unsupported integrations."] = "I profili conservano impostazioni dei moduli e layout separati. In Profili puoi creare, copiare, rinominare, scegliere, importare, esportare o eliminare un profilo. Puoi anche assegnare profili ai gruppi talenti quando il client li supporta. /badb profile elenca i profili; /badb profile <nome> ne seleziona uno.\nI preset offrono layout iniziali per classe, ruolo, PvE e PvP. Leggi l'anteprima prima di applicare. Il flusso dei preset crea un backup e normalmente un nuovo profilo. /badb undo annulla l'ultima operazione preset se il profilo precedente esiste ancora.\nI backup sono snapshot salvati per il recupero. Creane uno prima di sperimentare, poi ripristinalo o esportalo da Backup. Export di profilo ed export di backup hanno ambiti diversi: leggi l'anteprima di importazione prima di applicarli.\nImport / Export copia un profilo intero o le opzioni di un modulo. Copia tutta la stringa generata. Importare impostazioni non installa altri addon e non crea profili nelle integrazioni non supportate.",
    ["Move frames and customize the look"] = "Sposta i frame e personalizza l'aspetto",
    ["Use Appearance to change the theme, accent, background opacity and settings-window scale. Scaling controls the game UI scale. ElvUI Style applies a coordinated look; review its changes and backup first.\nType /badb unlock to move supported frames, then use it again to lock them. Drag to move; use the arrow keys and Shift + mouse wheel where the mover supports them. Layout Studio adds selection, alignment, spacing and undo/redo tools.\nBlizzard frames managed by Edit Mode must use the client-supported layout controls. Edit Mode Bridge saves and reapplies the supported layout with a profile. Some built-in layouts must be duplicated in Edit Mode before they can be edited.\nIf a frame cannot move or resize, check its module, the active profile, combat state and Edit Mode support. Avoid having two addons control the same frame."] = "Usa Aspetto per cambiare tema, accento, trasparenza degli sfondi e scala della finestra. Scaling controlla la scala dell'interfaccia di gioco. Stile ElvUI applica un aspetto coordinato: controlla prima modifiche e backup.\nScrivi /badb unlock per spostare i frame supportati e ripetilo per bloccarli. Trascina per muovere; usa frecce e Maiusc + rotella dove supportato. Layout Studio aggiunge selezione, allineamento, spaziatura e annulla/ripeti.\nI frame Blizzard gestiti da Edit Mode devono usare i controlli di layout supportati dal client. Edit Mode Bridge salva e riapplica il layout supportato insieme al profilo. Alcuni layout predefiniti vanno duplicati in Edit Mode prima di modificarli.\nSe un frame non si sposta o ridimensiona, controlla modulo, profilo attivo, combattimento e supporto Edit Mode. Evita che due addon controllino lo stesso frame.",
    ["Macro catalog: class, specialization, PvE and PvP"] = "Catalogo macro: classe, specializzazione, PvE e PvP",
    ["Open Macros with /badb macro. Choose Class, Specialization and Content to browse shared, PvE and PvP entries. Read Code and the notes before turning a macro on: a listed spell may need a talent, training or a specific client feature.\nTurn on creates the macro in the game's /macro panel. Pick up puts an active macro on your cursor so you can drag it onto an action bar. Press that action-bar button yourself to execute it. Turning on a catalog entry does not automatically play your character.\nTurn off removes an unchanged macro created by BadbUI. A user macro with the same name is never overwritten, and a catalog macro edited by hand is kept. Disabling the Macros module does not delete created macros.\nSlots are limited: enable only the entries you need. Creation and editing are unavailable in combat. Custom bodies must fit the engine's 255-character limit and names its 16-character limit. The client may expose different slot capacities.\nUse /badb macro list <spec> pve (or pvp), /badb macro show <name>, /badb macro on <name>, /badb macro off <name>. /badb macro alloff requests removal of all unchanged managed macros; use it intentionally.\nMacro bodies remain in English. Catalog entries have not been verified inside the Forever client; check abilities, conditionals and focus/arena units in game before relying on them."] = "Apri Macro con /badb macro. Scegli Class, Specialization e Content per vedere voci comuni, PvE e PvP. Leggi Code e le note prima di accendere una macro: un'abilita' puo' richiedere talenti, addestramento o funzioni specifiche del client.\nTurn on crea la macro nel pannello /macro del gioco. Pick up mette una macro attiva sul cursore per trascinarla su una barra. Premi tu il pulsante sulla barra per eseguirla. Accendere una voce non fa giocare automaticamente il personaggio.\nTurn off rimuove una macro non modificata creata da BadbUI. Una macro dell'utente con lo stesso nome non viene sovrascritta e una macro del catalogo modificata a mano viene conservata. Spegnere il modulo Macro non elimina le macro create.\nGli slot sono limitati: attiva solo cio' che ti serve. Creazione e modifica non sono disponibili in combattimento. I testi personalizzati devono rispettare il limite del motore di 255 caratteri e i nomi quello di 16. Il client puo' esporre capacita' degli slot diverse.\nUsa /badb macro list <spec> pve (oppure pvp), /badb macro show <nome>, /badb macro on <nome>, /badb macro off <nome>. /badb macro alloff richiede la rimozione di tutte le macro gestite non modificate: usalo consapevolmente.\nI testi delle macro restano in inglese. Le voci del catalogo non sono state verificate nel client Forever: controlla in gioco abilita', condizioni e unita' focus/arena prima di farci affidamento.",
    ["Automatic profiles and other addons"] = "Profili automatici e altri addon",
    ["Contexts can switch profiles using rules for content, instance, class, role, specialization or group. Check rule priority and whether automatic switching is enabled. A manual profile change can suspend switching. Inspect the current context before changing a rule.\nIntegrations can capture and reapply supported settings from installed addons. Support differs by addon; some adapters only report status. Read the status and warnings before Apply or Reset. The other addon must be installed and its required profile must exist.\nIf settings keep changing unexpectedly, check Contexts, specialization assignments and integrations. For conflicts, choose one addon to control each set of bars, frames or nameplates."] = "Contesti puo' cambiare profilo tramite regole per contenuto, istanza, classe, ruolo, specializzazione o gruppo. Controlla priorita' delle regole e cambio automatico. Un cambio manuale del profilo puo' sospendere l'automatismo. Controlla il contesto attuale prima di modificare una regola.\nIntegrazioni cattura e riapplica le impostazioni supportate degli addon installati. Il supporto varia: alcuni adattatori mostrano solo lo stato. Leggi stato e avvisi prima di Applica o Reset. L'altro addon deve essere installato e il profilo richiesto deve esistere.\nSe le impostazioni cambiano in modo inatteso, controlla Contesti, assegnazioni per specializzazione e integrazioni. Per i conflitti, scegli un solo addon che controlli ciascun insieme di barre, frame o nameplate.",
    ["Scripts and automation"] = "Script e automazione",
    ["The script editor manages your own Lua snippets with manual, login, event or timer triggers. Read the code before enabling or importing a script. Use clear names and test one script at a time.\nScripts use the addon environment and remain subject to the client's protected-action and combat restrictions. Repeated script errors can stop a script automatically. Use Stop or turn the script off, then inspect its error and the addon log.\nScripts, imported code and macro bodies are not translated when you change the interface language. The editor and command help explain the supported triggers and controls."] = "L'editor gestisce i tuoi script Lua con trigger manuale, accesso, evento o timer. Leggi il codice prima di attivare o importare uno script. Usa nomi chiari e prova uno script alla volta.\nGli script usano l'ambiente dell'addon e rispettano i limiti del client sulle azioni protette e sul combattimento. Errori ripetuti possono fermare automaticamente uno script. Usa Ferma o spegnilo, poi controlla errore e log dell'addon.\nScript, codice importato e testi delle macro non vengono tradotti quando cambi lingua all'interfaccia. L'editor e l'aiuto dei comandi spiegano trigger e controlli supportati.",
    ["Guild and companion"] = "Gilda e companion",
    ["The guild panel shows the server snapshot: raid calendar, signups, weekly availability, tactics, guild news, guides and armory. These features need a connected companion; the interface modules and local manual work without it.\nInstall the companion and link the addon code from your website profile. Use /badb guildscan to refresh your character snapshot, then /reload to write SavedVariables for the companion. Wait for the companion to finish, then /reload again to load the updated server snapshot.\nGuild answers are queued locally and sent through the companion. If data looks old, check the snapshot time and pending actions, then the companion's connection. Server text remains in the author's language. Tactical ratings are officer assessments, not official combat statistics."] = "Il pannello Gilda mostra lo snapshot del server: calendario raid, iscrizioni, disponibilita' settimanale, tattiche, notizie, guide e armory. Queste funzioni richiedono il companion collegato; moduli dell'interfaccia e manuale locale funzionano anche senza.\nInstalla il companion e collega il codice addon dal tuo profilo sul sito. Usa /badb guildscan per aggiornare lo snapshot del personaggio, poi /reload per scrivere le SavedVariables per il companion. Attendi che finisca e usa di nuovo /reload per caricare lo snapshot aggiornato del server.\nLe risposte di gilda vengono accodate localmente e inviate tramite il companion. Se i dati sono vecchi, controlla data dello snapshot e azioni in coda, poi la connessione del companion. I testi del server restano nella lingua dell'autore. Le valutazioni tattiche sono giudizi degli ufficiali, non statistiche ufficiali di combattimento.",
    ["Guides and learning"] = "Guide e apprendimento",
    ["Open the guide library with /badb guide. Search by keyword, filter categories and save useful entries with the bookmark star. Guides can include steps whose completion you track, links to copy and zone-based suggestions.\nThe starter library covers setup, profiles, class templates, Edit Mode, sharing, integrations, client restrictions, roles, PvE, PvP and troubleshooting. Use a topic's Read guide button for a deeper explanation.\nGuide titles and built-in text follow the addon language. Content marked uncertain still needs in-game verification; a translated guide does not confirm a game mechanic. Imported guides and linked websites may use other languages."] = "Apri la libreria con /badb guide. Cerca per parola chiave, filtra le categorie e salva le voci utili con la stella dei segnalibri. Le guide possono includere passi da segnare come completati, link da copiare e suggerimenti per zona.\nLa libreria iniziale tratta configurazione, profili, template per classe, Edit Mode, condivisione, integrazioni, limiti del client, ruoli, PvE, PvP e problemi comuni. Usa Leggi guida in un argomento per approfondire.\nTitoli e testi integrati seguono la lingua dell'addon. I contenuti indicati come incerti richiedono ancora verifica in gioco: una guida tradotta non conferma una meccanica. Guide importate e siti collegati possono usare altre lingue.",
    ["Troubleshooting and recovery"] = "Problemi comuni e recupero",
    ["Cannot change a setting? Leave combat and try again. Check that the module is on, that you are editing the intended profile, and that the client exposes the required API.\nSomething disappeared? Check Hider, module visibility and the active profile. Unlock supported frames to find misplaced elements. Restore a backup if needed; avoid resetting everything as your first step.\nUnexpected appearance or repeated changes? Check for another UI addon controlling the same elements, Contexts rules and specialization profile assignments.\nMacro does not work? Check the spell name in the game client, learned abilities and talents, valid target/focus, macro notes, combat state and free slots. Turn on only creates it; you must place and press it on a bar.\nRun /badb doctor run for checks. /badb doctor report opens a report you can copy, /badb doctor errors shows captured errors, and /badb log shows recent addon messages. Review a report before sharing it; include your client build, addon version and exact steps to reproduce the issue.\nRestore a known backup or use /badb undo for the last preset where available. /reload restarts the interface and applies a pending language change."] = "Non riesci a cambiare un'impostazione? Esci dal combattimento e riprova. Controlla che il modulo sia acceso, che il profilo sia quello giusto e che il client esponga l'API richiesta.\nQualcosa e' sparito? Controlla Hider, visibilita' dei moduli e profilo attivo. Sblocca i frame supportati per ritrovare elementi fuori posto. Se serve ripristina un backup; evita di azzerare tutto come primo tentativo.\nAspetto inatteso o modifiche ripetute? Controlla altri addon UI sugli stessi elementi, regole di Contesti e assegnazioni dei profili alle specializzazioni.\nUna macro non funziona? Controlla nome dell'abilita' nel client, abilita' apprese e talenti, bersaglio/focus valido, note, combattimento e slot liberi. Turn on la crea soltanto: devi metterla sulla barra e premerla.\nEsegui /badb doctor run per i controlli. /badb doctor report apre un report da copiare, /badb doctor errors mostra gli errori catturati e /badb log i messaggi recenti. Rileggi il report prima di condividerlo; includi build del client, versione addon e passi esatti per riprodurre il problema.\nRipristina un backup noto oppure usa /badb undo per l'ultimo preset, quando disponibile. /reload riavvia l'interfaccia e applica un cambio lingua in attesa.",
    ["Client compatibility and limits"] = "Compatibilita' e limiti del client",
    ["BadbUI targets WoW: Forever. Available APIs and protected actions depend on the game client. Some features may be unavailable, deferred until combat ends, or require in-game verification.\nSecret values cannot be safely inspected like ordinary Lua data. Addon scripts cannot bypass protected actions, combat restrictions or unavailable combat-log APIs. Role detection can be uncertain; use /badb role <tank|healer|dps|auto> when you need to confirm or clear a role override.\nBuilt-in UI translations support English and Italian. This does not imply verified compatibility with every localized game client. Macro spell names stay in English by default, and guild content keeps its original language."] = "BadbUI e' pensato per WoW: Forever. API disponibili e azioni protette dipendono dal client. Alcune funzioni possono essere assenti, rinviate a fine combattimento o richiedere verifica in gioco.\nI secret values non si possono ispezionare come normali dati Lua. Gli script non aggirano azioni protette, limiti in combattimento o API combat log assenti. Il rilevamento del ruolo puo' essere incerto: usa /badb role <tank|healer|dps|auto> per confermare o rimuovere il ruolo scelto.\nLe traduzioni dell'interfaccia supportano inglese e italiano. Questo non significa che ogni client localizzato sia stato verificato. I nomi delle abilita' nelle macro restano in inglese per impostazione predefinita e i contenuti di gilda conservano la lingua originale.",
    ["Style action buttons, keybind and macro text, range feedback and mouseover fading."] = "Personalizza pulsanti, testi dei tasti e macro, feedback distanza e dissolvenza al mouse.",
    ["Configure defensive and healer alerts, watched units, sound and position."] = "Configura avvisi difensivi e healer, unita' sorvegliate, suono e posizione.",
    ["Manage the shared aura catalog, categories, priorities and custom entries used by other modules."] = "Gestisci catalogo aure condiviso, categorie, priorita' e voci personalizzate usate dagli altri moduli.",
    ["Create, inspect, export and restore saved snapshots."] = "Crea, esamina, esporta e ripristina snapshot salvati.",
    ["Set rules that choose profiles for your current content, role and group."] = "Imposta regole per scegliere i profili in base a contenuto, ruolo e gruppo.",
    ["Customize countdown numbers, cooldown animations and pulse feedback."] = "Personalizza numeri dei cooldown, animazioni e feedback pulse.",
    ["Configure experience and reputation bars, text, size and visibility."] = "Configura barre esperienza e reputazione, testi, dimensioni e visibilita'.",
    ["Inspect compatibility, conflicts and captured errors; generate a report and review offered repairs."] = "Controlla compatibilita', conflitti ed errori; genera un report e valuta le riparazioni proposte.",
    ["Save and restore supported Blizzard Edit Mode layouts with profiles."] = "Salva e ripristina i layout Blizzard Edit Mode supportati insieme ai profili.",
    ["Apply coordinated styling to the interface, datatext panels, minimap and chat."] = "Applica uno stile coordinato a interfaccia, pannelli datatext, minimappa e chat.",
    ["Style Blizzard party and raid frames, health text, size and visual feedback."] = "Personalizza frame Blizzard di gruppo e raid, testi vita, dimensioni e feedback visivo.",
    ["View the guild snapshot and queue signups and availability through the companion."] = "Consulta lo snapshot di gilda e invia iscrizioni e disponibilita' tramite il companion.",
    ["Read and search built-in guides, manage bookmarks and track guide steps."] = "Leggi e cerca le guide integrate, gestisci segnalibri e passi completati.",
    ["Hide selected Blizzard interface elements; check here if something is missing."] = "Nascondi elementi Blizzard selezionati; controlla qui se qualcosa e' sparito.",
    ["Inspect installed-addon support, capture settings and reapply supported profiles."] = "Verifica il supporto degli addon installati, cattura impostazioni e riapplica i profili supportati.",
    ["Select, move, align and space supported frames with undo and redo."] = "Seleziona, sposta, allinea e distribuisci i frame supportati con annulla e ripeti.",
    ["Browse ready-made class and specialization macros for PvE and PvP and manage created entries."] = "Sfoglia macro pronte per classe e specializzazione, PvE e PvP, e gestisci le voci create.",
    ["Choose which important buffs and debuffs appear on nameplates."] = "Scegli quali buff e debuff importanti mostrare sulle nameplate.",
    ["Set enemy and friendly nameplate visibility, stacking, scale and target highlighting."] = "Imposta visibilita' delle nameplate nemiche e alleate, impilamento, scala e bersaglio.",
    ["Preview and apply starting layouts for class, role and content, then undo when supported."] = "Controlla e applica layout iniziali per classe, ruolo e contenuto, poi annulla quando supportato.",
    ["Set the game UI scale and pixel-perfect scaling options."] = "Imposta scala dell'interfaccia di gioco e opzioni pixel perfect.",
    ["Create and manage Lua scripts and manual, login, event or timer triggers."] = "Crea e gestisci script Lua e trigger manuali, accesso, evento o timer.",
    ["Customize tooltip backgrounds, class and item-quality borders, and health bars."] = "Personalizza sfondi dei tooltip, bordi per classe e qualita' degli oggetti e barre vita.",
    ["Configure player, target, target-of-target, focus and party frames, text, auras and cast bars."] = "Configura frame giocatore, bersaglio, bersaglio del bersaglio, focus e gruppo, testi, aure e barre di lancio.",
    ["Run guided setup, review its proposed changes and confirm uncertain role detection."] = "Avvia la configurazione guidata, controlla le modifiche e conferma il ruolo se incerto.",
})

ns.Badb.Localization:RegisterLocale("itIT", {
    ["Help"] = "Aiuto",
    ["Every module explained"] = "Tutti i moduli spiegati",
    ["Each module can be enabled independently. Open its options from here or from Home. A disabled module's page explains how to enable it."] = "Ogni modulo si puo' attivare separatamente. Apri le opzioni da qui o da Principale. La pagina di un modulo spento spiega come attivarlo.",
    ["Open this module's options to inspect its available settings."] = "Apri le opzioni del modulo per vedere le impostazioni disponibili.",
    ["All slash commands"] = "Tutti i comandi",
    ["Use /badb or /bui before a command. Names stay the same in every language. <...> marks a required value; [...] marks an optional value. Do not type the brackets. Commands below are discovered from the installed modules."] = "Usa /badb oppure /bui prima di un comando. I nomi restano uguali in ogni lingua. <...> indica un valore obbligatorio; [...] un valore facoltativo. Non scrivere le parentesi. I comandi elencati vengono rilevati dai moduli installati.",
    ["All topics"] = "Tutti gli argomenti",
    ["Everything you need to get started, customize the interface and recover from problems. Available offline in English and Italian."] = "Tutto cio' che serve per iniziare, personalizzare l'interfaccia e risolvere i problemi. Disponibile anche offline in inglese e italiano.",
    ["Topic"] = "Argomento",
    ["Search all help (press Enter)"] = "Cerca in tutto l'aiuto (premi Invio)",
    ["Clear search / show all topics"] = "Cancella ricerca / mostra tutti gli argomenti",
    ["No help topics match. Try another word or clear the search."] = "Nessun argomento trovato. Prova un'altra parola o cancella la ricerca.",
    ["Open settings"] = "Apri impostazioni",
    ["Open guild panel"] = "Apri pannello gilda",
    ["Read guide"] = "Leggi guida",
    ["Open options"] = "Apri opzioni",
    ["Open the manual and list commands; help [topic]"] = "Apri il manuale ed elenca i comandi; help [argomento]",
})

ns.Badb.Localization:RegisterLocale("itIT", {
    ["Read the manual, explore all modules and find answers"] = "Leggi il manuale, scopri tutti i moduli e trova le risposte",
})

ns.Badb.Localization:RegisterLocale("itIT", {
    ["Reload outside combat."] = "Ricarica fuori dal combattimento.",
    ["Open settings outside combat."] = "Apri le impostazioni fuori dal combattimento.",
    ["Chatbot settings · nikcli embedded"] = "Impostazioni chatbot · nikcli embedded",
    ["Provider ID (including custom nikcli providers)"] = "ID provider (inclusi i provider nikcli personalizzati)",
    ["API key · leave blank to keep existing credentials"] = "Chiave API · lascia vuoto per mantenere le credenziali esistenti",
    ["Keys entered here pass through local SavedVariables until acknowledged and reloaded. Never share that file or its .bak backup."] = "Le chiavi inserite passano dalle SavedVariables locali fino alla conferma e al reload. Non condividere quel file o il backup .bak.",
    ["Save API key"] = "Salva chiave API",
    ["Enter a provider ID and API key."] = "Inserisci ID provider e chiave API.",
    ["Disconnect provider"] = "Scollega provider",
    ["Remove this provider's stored nikcli credentials?"] = "Rimuovere le credenziali nikcli salvate di questo provider?",
    ["OAuth method"] = "Metodo OAuth",
    ["Start login"] = "Avvia accesso",
    ["This provider has no OAuth method. Refresh providers first."] = "Questo provider non ha metodi OAuth. Aggiorna prima i provider.",
    ["OAuth callback code (when required)"] = "Codice di callback OAuth (quando richiesto)",
